classDiagram
  direction LR
  class Order {
    +OrderId id
    +OrderStatus status
    +Money total
    +addItem(product, quantity)
    +confirm()
    +cancel(reason)
  }
  class OrderItem {
    +ProductId productId
    +int quantity
    +Money unitPrice
  }
  class Customer {
    +CustomerId id
    +Email email
  }
  class Payment {
    +PaymentId id
    +PaymentStatus status
    +authorize()
    +capture()
    +void()
  }
  class PaymentGateway {
    <<interface>>
    +authorize(request)
    +capture(id)
  }
  class InventoryReservation {
    +ReservationId id
    +reserve()
    +release()
  }
  class Shipment {
    +ShipmentId id
    +TrackingCode tracking
    +dispatch()
  }
  class OrderRepository {
    <<interface>>
    +find(id) Order
    +save(order)
  }
  Customer "1" --> "0..*" Order : places
  Order "1" *-- "1..*" OrderItem : contains
  Order "1" o-- "0..1" Payment : payment
  Order "1" o-- "0..1" InventoryReservation : inventory
  Order "1" o-- "0..1" Shipment : fulfillment
  Payment --> PaymentGateway : delegates
  OrderRepository ..> Order : persists

classDiagram
  direction TB
  namespace Definition {
    class WorkflowDefinition {
      +String key
      +int version
      +List~StepDefinition~ steps
      +validate() Result
    }
    class StepDefinition {
      <<abstract>>
      +String id
      +Duration timeout
    }
    class HttpStep {
      +URI endpoint
      +Map~String,String~ headers
    }
    class DecisionStep {
      +Expression condition
    }
  }
  namespace Runtime {
    class WorkflowInstance {
      +InstanceId id
      +InstanceStatus status
      +advance(event)
    }
    class StepExecution {
      +ExecutionId id
      +int attempt
      +ExecutionStatus status
    }
    class Scheduler {
      +schedule(instance)
      +retry(execution)
    }
    class StateStore {
      <<interface>>
      +load(id) WorkflowInstance
      +commit(instance)
    }
  }
  StepDefinition <|-- HttpStep
  StepDefinition <|-- DecisionStep
  WorkflowDefinition "1" *-- "1..*" StepDefinition
  WorkflowInstance "1" *-- "0..*" StepExecution
  Scheduler --> StateStore
  WorkflowInstance --> WorkflowDefinition : executes
  StepExecution --> StepDefinition : realizes

classDiagram
  class Principal {
    <<interface>>
    +PrincipalId id
  }
  class User {
    +String email
    +UserStatus status
  }
  class Group {
    +String name
  }
  class Role {
    +String name
    +Set~Permission~ permissions
  }
  class Permission {
    +String action
    +String resourceType
  }
  class Grant {
    +Instant startsAt
    +Instant expiresAt
    +Scope scope
  }
  class Policy {
    +Effect effect
    +Expression condition
  }
  class Evaluator {
    +evaluate(request) Decision
  }
  class AuditSink {
    <<interface>>
    +append(decision)
  }
  Principal <|.. User
  Principal <|.. Group
  Group "0..*" o-- "0..*" User : members
  Grant --> Principal : subject
  Grant --> Role : assigns
  Role "1" *-- "1..*" Permission
  Policy --> Permission : constrains
  Evaluator --> Grant : resolves
  Evaluator --> Policy : applies
  Evaluator --> AuditSink : records

classDiagram
  class Notification {
    +NotificationId id
    +Recipient recipient
    +Map~String,Any~ variables
  }
  class Template {
    +TemplateId id
    +Locale locale
    +render(variables) Message
  }
  class PreferenceService {
    +allowed(recipient, channel) bool
  }
  class Router {
    +route(notification) List~Channel~
  }
  class Channel {
    <<interface>>
    +send(message) DeliveryReceipt
  }
  class EmailChannel
  class PushChannel
  class SmsChannel
  class RetryPolicy {
    +int maxAttempts
    +Duration nextDelay(attempt)
  }
  class DeliveryStore {
    <<interface>>
    +save(receipt)
    +pending() List~DeliveryReceipt~
  }
  Notification --> Template : renders with
  Router --> PreferenceService : checks
  Router --> Channel : selects
  Channel <|.. EmailChannel
  Channel <|.. PushChannel
  Channel <|.. SmsChannel
  Channel --> RetryPolicy : follows
  Channel --> DeliveryStore : records

classDiagram
  class Document {
    +DocumentId id
    +Revision revision
    +List~Block~ blocks
    +apply(operation)
  }
  class Block {
    <<abstract>>
    +BlockId id
    +Position position
  }
  class TextBlock {
    +String text
    +List~Mark~ marks
  }
  class MediaBlock {
    +URI source
    +Dimensions size
  }
  class Operation {
    +OperationId id
    +Revision baseRevision
    +transform(other) Operation
  }
  class Revision {
    +long sequence
    +Instant committedAt
  }
  class Session {
    +SessionId id
    +UserId user
    +Cursor cursor
  }
  class SyncEngine {
    +merge(local, remote) MergeResult
  }
  class DocumentStore {
    <<interface>>
    +load(id) Document
    +commit(document, operations)
  }
  Block <|-- TextBlock
  Block <|-- MediaBlock
  Document "1" *-- "1..*" Block
  Document "1" o-- "0..*" Revision
  Document "1" o-- "0..*" Session
  SyncEngine --> Operation
  SyncEngine --> DocumentStore

